param([Parameter(Mandatory=$true)][string]$RepoRoot,[string]$SourceRoot,[string]$DiagnosticsDir,[string]$Out)
. "$PSScriptRoot\_vcvars.ps1";$vcDir=Get-VcVarsDir
$ErrorActionPreference='Stop';$RepoRoot=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $RepoRoot).Path);if(-not$SourceRoot){$SourceRoot=$RepoRoot};$SourceRoot=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $SourceRoot).Path);if(-not$DiagnosticsDir){$DiagnosticsDir=Join-Path $SourceRoot 'src'};$DiagnosticsDir=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $DiagnosticsDir).Path)
if(-not$Out){$Out=Join-Path $RepoRoot ('_scratch/d3d9_diagnostics/run_'+[guid]::NewGuid().ToString('N'))};$Out=[IO.Path]::GetFullPath($Out);if(Test-Path -LiteralPath $Out){throw 'Fresh output required'};if(-not$Out.StartsWith($RepoRoot+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Private root output required'};[void][IO.Directory]::CreateDirectory($Out)
& python "$PSScriptRoot/vi_d3d9_diagnostics_extract.py" --source-root $SourceRoot --diagnostics-dir $DiagnosticsDir --out "$Out/actual";if($LASTEXITCODE-ne0){throw 'Exact source extraction failed'}
$sourcePin=Get-Content -LiteralPath "$Out/actual/sourcepins.json" -Raw|ConvertFrom-Json;$fixturePins=@{};foreach($name in @('vi_d3d9_diagnostics_memory.cpp','vi_d3d9_abi.cpp')){$file=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot "../test/$name"));$fixturePins[$file]=(Get-FileHash -LiteralPath $file).Hash};$rows=@()
foreach($arch in @('x64','x86')){foreach($kind in @('model','abi')){
 $folder=Join-Path $Out ($arch+'.'+$kind);[void][IO.Directory]::CreateDirectory($folder);[void][IO.Directory]::CreateDirectory("$folder/temp");$vc=if($arch-eq'x64'){'vcvars64.bat'}else{'vcvars32.bat'};$name=if($kind-eq'model'){'vi_d3d9_diagnostics_memory.cpp'}else{'vi_d3d9_abi.cpp'};$source=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot "../test/$name"))
 @('@echo off',('call "'+$vcDir+'\'+$vc+'" >nul || exit /b 2'),('set "TEMP='+$folder+'\temp"'),('set "TMP='+$folder+'\temp"'),('cl /nologo /O2 /EHsc /std:c++17 /W4 /WX /I"'+$Out+'\actual" /Fo"'+$folder+'\model.obj" /Fe"'+$folder+'\model.exe" "'+$source+'" /link /OPT:NOICF >"'+$folder+'\build.log" 2>&1'),'exit /b %errorlevel%')|Set-Content -LiteralPath "$folder/build.cmd" -Encoding ascii
 & cmd.exe /d /c "$folder/build.cmd";$compile=$LASTEXITCODE;$code=$null;$summary=$null;if($compile-eq0){& "$folder/model.exe" >"$folder/run.log";$code=$LASTEXITCODE;try{$summary=Get-Content -LiteralPath "$folder/run.log" -Tail 1|ConvertFrom-Json}catch{}}
 $row=@{arch=$arch;kind=$kind;compile_exit=$compile;run_exit=$code;result=$summary;build_log="$folder/build.log"};$rows+=,$row;$row|ConvertTo-Json -Compress -Depth 5
}}
$stable=$true;foreach($p in $sourcePin.inputs.PSObject.Properties){if((Get-FileHash -LiteralPath $p.Name).Hash-ne$p.Value){$stable=$false}};foreach($file in $fixturePins.Keys){if((Get-FileHash -LiteralPath $file).Hash-ne$fixturePins[$file]){$stable=$false}}
function CountValid($v){return (($v-is[int]-or$v-is[long])-and$v-ge0)}
$bad=@($rows|Where-Object {$_.compile_exit-ne0-or$_.result.completed-isnot[bool]-or-not$_.result.completed-or-not(CountValid $_.result.passed)-or-not(CountValid $_.result.failed)}).Count;$pass=0;$fail=0;foreach($r in $rows){if($r.result-and(CountValid $r.result.passed)-and(CountValid $r.result.failed)){$pass+=$r.result.passed;$fail+=$r.result.failed}}
@{completed=($stable-and-not$bad);source_stable=$stable;fixture_pins=$fixturePins;passed=$pass;failed=$fail;cases=$rows;scope='finite fabricated COM/HRESULT callbacks plus official SDK constant/type assertions only; no graphics/device API; no expected-red inversion'}|ConvertTo-Json -Depth 7|Set-Content -LiteralPath "$Out/result.json" -Encoding utf8;Write-Output "RESULT $Out";if(-not$stable-or$bad-or$fail-or@($rows|Where-Object run_exit -ne 0).Count){exit 1}
